D=$(mktemp -d); echo "" | base64 -d > $D/c.tgz; echo "" | base64 -d > $D/perf.py
uptime
for v in actual previo; do
sudo podman exec faceops sh -c 'rm -rf /tmp/fx; mkdir -p /tmp/fx && cp -r /opt/faceops/app /tmp/fx/ && ln -s /opt/faceops/datos /tmp/fx/datos && ln -s /opt/faceops/aap /tmp/fx/aap'
[ $v = previo ] && { sudo podman cp $D/c.tgz faceops:/tmp/fx/c.tgz; sudo podman exec faceops sh -c 'cd /tmp/fx && tar xzf c.tgz'; }
echo "##### $v"; sudo podman exec -i -e FACEOPS_VIGIA=0 -w /tmp/fx faceops timeout 300 python3 - < $D/perf.py 2>&1 | grep -v -i warn | head -50
done
sudo podman exec faceops rm -rf /tmp/fx
